#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# rask on a new computer: the toolchain, the repo, the handover kit, and the estate rebuilt from empty.
# Run on the NEW machine after copying the kit made on the old one (see HANDOVER.md in the kit):
#   tar xzf rask-handover-*.tar.gz -C ~   &&   bash ~/rask-handover-*/new-machine.sh   (or scripts/new-machine.sh)
# Every stage is safe to re-run: each skips what is already done.

TOTAL_STAGES=8
have() { command -v "$1" >/dev/null 2>&1; }
DAGGER_VERSION="0.21.8"   # dagger.json engineVersion

banner "rask on a new computer"

stage "Prerequisites"
say "The estate runs on k3s (sudo). Docker hosts the dev image registry and the Dagger engine; nothing else uses it."
for tool in git curl sudo make docker; do
  if have "$tool"; then step "$tool: found"; else warn "$tool: missing"; SKIPPED+=("install $tool"); fi
done
if ! have docker; then
  open_url "https://docs.docker.com/engine/install/"
  note "Install Docker Engine, add yourself to the docker group (log out and in), then re-run this wizard."
fi
pause

stage "Command-line tools"
say "uv (Python), bun (frontend), prek (git hooks), the Dagger CLI pinned at v$DAGGER_VERSION, gh and Claude Code."
export PATH="$HOME/.local/bin:$HOME/.bun/bin:$PATH"
have uv  || { step "installing uv";  curl -LsSf https://astral.sh/uv/install.sh | sh; }
have bun || { step "installing bun"; curl -fsSL https://bun.sh/install | bash; }
have prek || { step "installing prek"; uv tool install prek; }
if ! have dagger || ! dagger version 2>/dev/null | grep -q "v$DAGGER_VERSION"; then
  step "installing the Dagger CLI v$DAGGER_VERSION into ~/.local/bin"
  curl -fsSL https://dl.dagger.io/dagger/install.sh | DAGGER_VERSION="$DAGGER_VERSION" BIN_DIR="$HOME/.local/bin" sh
fi
if ! have gh; then
  open_url "https://github.com/cli/cli#installation"
  pause "Install gh from that page, then press Enter"
fi
if ! have claude; then
  open_url "https://docs.claude.com/en/docs/claude-code/setup"
  pause "Install Claude Code from that page, then press Enter"
fi
for tool in uv bun prek dagger gh claude; do have "$tool" && step "$tool: $(command -v "$tool")" || { warn "$tool still missing"; SKIPPED+=("install $tool"); }; done
note "Add ~/.local/bin and ~/.bun/bin to PATH in your shell profile if they are not there."
pause

stage "Sign in to GitHub"
if gh auth status >/dev/null 2>&1; then step "gh is already signed in"; else
  say "gh signs in through the browser; choose HTTPS and authenticate git with your GitHub credentials."
  gh auth login
fi

stage "Clone the repository"
REPO_DIR="${REPO_DIR:-$HOME/Desktop/rask}"
ask REPO_DIR "Where should rask live? [$REPO_DIR]"
REPO_DIR="${REPO_DIR:-$HOME/Desktop/rask}"
if [[ -d "$REPO_DIR/.git" ]]; then step "already cloned at $REPO_DIR"; else gh repo clone AI-Riksarkivet/rask "$REPO_DIR"; fi
cd "$REPO_DIR"

stage "Restore the handover kit"
KIT="${KIT:-$(ls -d "$HOME"/rask-handover-* 2>/dev/null | tail -n1)}"
ask KIT "Path to the unpacked handover kit [$KIT]"
[[ -d "$KIT" ]] || { warn "no kit at $KIT"; SKIPPED+=("restore the handover kit"); pause; }
if [[ -d "$KIT" ]]; then
  [[ -f .env ]] && step ".env exists; keeping it" || { cp "$KIT/dot-env" .env; step "restored .env (holds credentials: keep it out of git)"; }
  mkdir -p .claude && cp "$KIT/settings.local.json" .claude/settings.local.json && step "restored .claude/settings.local.json"
  # Claude Code keys a project's memory by its absolute path, every `/` a `-`.
  MEM="$HOME/.claude/projects/$(printf '%s' "$REPO_DIR" | tr '/' '-')/memory"
  mkdir -p "$MEM" && cp -n "$KIT"/memory/* "$MEM"/ && step "restored $(ls "$MEM" | wc -l) memory files into $MEM"
  git fetch -q "$KIT/rask-local.bundle" 'refs/heads/*:refs/heads/local/*' && step "restored $(git branch --list 'local/*' | wc -l) local branches under local/"
  note "Only the newest stash travels in a bundle; the older ones are listed in $KIT/stashes.txt."
fi
pause

stage "Workspace and Claude Code"
make install
make claude-bootstrap
note "If a plugin seems stale later: claude plugin update <name> -s user, then restart Claude Code."
pause

stage "The estate: k3s, the dev registry, the Dagger engine"
say "This installs k3s and helm (sudo), the pinned tools into .localbin, starts the dev registry on :5000 and points k3s at it (restarts k3s),"
say "and starts the Dagger engine that may push to that registry."
if confirm "Install and configure them now?"; then
  make k3s-install
  # k3s-install brings helm, which make bootstrap requires on PATH before it fetches the rest into .localbin.
  make bootstrap
  make dev-registry
  make dagger-engine
  export KUBECONFIG=/etc/rancher/k3s/k3s.yaml
else
  SKIPPED+=("make k3s-install && make dev-registry && make dagger-engine")
fi

stage "Build the images and install rask from empty"
say "Every image the pins files name is built by Dagger from this checkout and pushed under that tag,"
say "so the committed pins stay valid; then make k3s-up installs the fixtures and rask."
if confirm "Build every pinned image and install? (a long run, once)"; then
  export _EXPERIMENTAL_DAGGER_RUNNER_HOST=docker-container://dagger-engine-rask KUBECONFIG=/etc/rancher/k3s/k3s.yaml
  push() { bash scripts/dagger-image.sh "$@" || { warn "build failed: $*"; SKIPPED+=("build $*"); }; }
  pins() { sed -n 's/^ *\([a-z0-9-]*\): *"\([^"]*\)".*/\1 \2/p' "$1"; }
  while read -r name tag; do
    case "$name" in
      lance-rest-catalog) push --name rest-catalog --push "172.17.0.1:5000/$name:$tag" ;;
      web-*)              push --zone "${name#web-}" --push "172.17.0.1:5000/$name:$tag" ;;
      *) if [[ -f ".docker/$name.dockerfile" ]]; then push --name "$name" --push "172.17.0.1:5000/$name:$tag"; else note "$name: public image, pulled as-is"; fi ;;
    esac
  done < <(pins deploy/values-live-pins.yaml)
  for f in deploy/fixtures/ray-cluster/values-live-pins.yaml deploy/fixtures/compute/values-live-pins.yaml; do
    [[ -f "$f" ]] || continue
    repo=$(sed -n 's/^ *repository: *"\(.*\)"/\1/p' "$f"); tag=$(sed -n 's/^ *tag: *"\(.*\)"/\1/p' "$f"); stem=${repo##*/}
    push --name "$stem" --push "172.17.0.1:5000/$stem:$tag"
  done
  make k3s-up
  step "rask is installed; checking it"
  make test
  bash scripts/e2e_live.sh -m cas
else
  SKIPPED+=("build the pinned images (this stage), then make k3s-up")
fi

finish
